import java.util.Scanner;
public class BubbleSort {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[] a = new int[n];
    for (int i = 0; i < n; i++)
      a[i] = sc.nextInt();
    for (int i = 0; i < n - 1; i++)
      for (int j = 0; j < n - 1 - i; j++)
        if (a[j] > a[j + 1]) {
          int t = a[j];
          a[j] = a[j + 1];
          a[j + 1] = t;
        }
    for (int i = 0; i < n; i++)
      System.out.print(a[i] + " ");
    System.out.println();
  }
}

import java.util.Scanner;
public class Yanghui {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int[][] a = new int[n][];
    for (int i = 0; i < n; i++) {
      a[i] = new int[i + 1];
      a[i][0] = a[i][i] = 1;
      for (int j = 1; j < i; j++)
        a[i][j] = a[i - 1][j - 1] + a[i - 1][j];
    }
    for (int i = 0; i < n; i++) {
      for (int j = 0; j <= i; j++)
        System.out.print(a[i][j] + " ");
      System.out.println();
    }
  }
}

